// Reduced from `solid-js@2.0.0-rc.21` and `@solidjs/signals@2.0.0-rc.21` types: `Component`, `DynamicOptions`, `Store<T> = T` with the plain
// `createStore` overload and `StoreSetter`.
export type Component<P = {}> = (props: P) => JSX.Element;
export interface DynamicOptions {
  static?: boolean;
}
export type StoreSetter<T> = (fn: (draft: T) => void) => void;
export declare function createStore<T extends object>(value: T): [T, StoreSetter<T>];
